DetectIntentRequest.newBuilder()
.setSession(
SessionName.ofProjectLocationAgentSessionName(
"[PROJECT]", "[LOCATION]", "[AGENT]", "[SESSION]")
.toString())
.setQueryParams(QueryParameters.newBuilder().build())
